package dashboard

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
)

// run is the watcher's explicit directory basename under repo/issues/issue-N.
// Using the status wire format keeps these tests executable against old
// watchers, which do not yet preserve this field, instead of failing to compile.
func act236WithRun(t *testing.T, step Step, run string) Step {
	t.Helper()
	b, err := json.Marshal(struct {
		Step
		Run string `json:"run,omitempty"`
	}{step, run})
	if err != nil {
		t.Fatal(err)
	}
	var out Step
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

func act236Public(t *testing.T, s *Server, now time.Time) act236Envelope {
	t.Helper()
	b, err := s.LiveJSON(now)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), `"command"`) || strings.Contains(string(b), `"commands"`) {
		t.Fatalf("public live response exposes commands: %s", b)
	}
	var e act236Envelope
	if err := json.Unmarshal(b, &e); err != nil {
		t.Fatal(err)
	}
	return e
}

func act236SameStrip(t *testing.T, private, public act236Envelope) {
	t.Helper()
	if len(private.Steps) != len(public.Steps) {
		t.Fatalf("public and private step counts differ: private %+v, public %+v", private, public)
	}
	for i := range private.Steps {
		if !reflect.DeepEqual(private.Steps[i].Live, public.Steps[i].Live) {
			t.Fatalf("public and private strips select different activity: private %+v, public %+v", private, public)
		}
	}
}

// Both signs matter: an old directory in an eastward zone can look newer
// than the UTC start, and the correct westward directory can look older.
func TestActShellCommandsUseRunIdentityAcrossTimeZones(t *testing.T) {
	for _, offset := range []int{9, -5} {
		t.Run(fmt.Sprintf("watcher_UTC%+d", offset), func(t *testing.T) {
			t.Parallel()
			act236Retry(t, time.FixedZone("watcher", offset*3600), false)
		})
	}
}

func TestActShellCommandsUseRunIdentityForSameSecondRetries(t *testing.T) {
	act236Retry(t, time.UTC, true)
}

func TestActShellCommandsWaitForTheCurrentRunTranscript(t *testing.T) {
	act236Retry(t, time.UTC, false)
}

// Drive status, directory creation, run publication, and transcript creation
// separately, in the watcher's order. Repeat with warm and cold readers.
func act236Retry(t *testing.T, watcher *time.Location, sameSecond bool) {
	t.Helper()
	for _, provider := range []string{"claude-code", "codex"} {
		for _, doing := range []string{"building", "formalizing", "answering"} {
			t.Run(provider+"/"+doing, func(t *testing.T) {
				t.Parallel()
				f := newAct236Fixture(t, provider)
				// Remove the helper's initial directory so only these two runs exist.
				if err := os.RemoveAll(filepath.Dir(f.path)); err != nil {
					t.Fatal(err)
				}
				prefix := "build-"
				if doing != "building" {
					prefix = "formalize-"
				}
				f.since = f.since.Add(100 * time.Millisecond)
				oldSince := f.since
				retry := oldSince.Add(time.Minute + 650*time.Millisecond)
				if sameSecond {
					retry = oldSince.Add(650 * time.Millisecond)
				}
				created := retry
				if doing != "building" && !sameSecond {
					created = retry.Add(3 * time.Second) // workspace preparation can delay creation
				}
				oldRun := prefix + oldSince.In(watcher).Format("20060102-150405") + "-z-previous"
				newRun := prefix + created.In(watcher).Format("20060102-150405") + "-a-current"
				issueDir := filepath.Join(f.work, "owner/app/issues/issue-236")
				f.path = filepath.Join(issueDir, oldRun, "transcript.jsonl")
				const oldCommand = "go build ./... # PRIVATE_PREVIOUS_RUN_236"
				act236Write(t, f.path, f.init(t)+f.start(t, "same-id", oldCommand, 0))
				f.status(t, act236WithRun(t, Step{Issue: 236, Doing: doing, Since: oldSince, Agent: provider}, oldRun))
				first := f.read(t)
				if len(first.Steps) != 1 || len(first.Steps[0].Commands) != 1 {
					t.Fatalf("previous run must be visible before retry: %+v", first)
				}
				if first.Steps[0].Commands[0].Command != oldCommand {
					t.Fatalf("wrong previous run: %+v", first)
				}
				act236SameStrip(t, first, act236Public(t, f.s, time.Now()))

				// New status comes first, with no run. Even a known agent name
				// is not permission to guess a transcript from directory times.
				f.status(t, Step{Issue: 236, Doing: doing, Since: retry, Agent: provider})
				f.append(t, f.done(t, "same-id", oldCommand, 61)+
					f.start(t, "old-late", "printf 'PRIVATE_LATE_PREVIOUS_RUN_236'", 62))
				oldPath := f.path

				cold := func() *act236Fixture {
					fresh := *f
					fresh.s = &Server{Work: f.work, Repos: f.s.Repos, Access: f.s.Access}
					return &fresh
				}
				assertNoRun := func(stage string) {
					t.Helper()
					// Refresh once after the existing two-second cache expires.
					// Do not poll until a transient disclosure disappears.
					time.Sleep(2100 * time.Millisecond)
					for _, reader := range []*act236Fixture{f, cold()} {
						e := reader.read(t)
						for _, step := range e.Steps {
							if len(step.Commands) != 0 {
								t.Fatalf("%s: old commands exposed before current transcript exists: %+v", stage, e)
							}
							// Ended public cards can retain their historical strip;
							// a current card may never inherit that activity.
							if step.Ended == nil && (len(step.Marks) != 0 || len(step.Tools) != 0) {
								t.Fatalf("%s: previous activity attributed to a current step: %+v", stage, step)
							}
						}
						act236SameStrip(t, e, act236Public(t, reader.s, time.Now()))
					}
				}
				assertNoRun("status before directory")

				f.path = filepath.Join(issueDir, newRun, "transcript.jsonl")
				if err := os.MkdirAll(filepath.Dir(f.path), 0o755); err != nil {
					t.Fatal(err)
				}
				f.status(t, act236WithRun(t, Step{Issue: 236, Doing: doing, Since: retry, Agent: provider}, newRun))
				assertNoRun("published run before transcript")

				f.since = created
				const newCommand = "git status --short"
				act236Write(t, f.path, f.init(t)+f.start(t, "same-id", newCommand, 1)+f.done(t, "same-id", newCommand, 2))
				// The previous transcript keeps growing and has a newer mtime;
				// neither that nor lexical directory order can select it.
				old := *f
				old.path = oldPath
				old.append(t, old.start(t, "late-again", "printf 'PRIVATE_OLD_AFTER_CURRENT_236'", 3))
				got := f.eventually(t, "current named transcript appears", func(e act236Envelope) bool {
					for _, step := range e.Steps {
						for _, command := range step.Commands {
							if command.Command != newCommand {
								t.Fatalf("retry restored previous commands: %+v", e)
							}
						}
					}
					return len(e.Steps) == 1 && len(e.Steps[0].Commands) == 1
				})
				step := got.Steps[0]
				if step.Since == nil || !step.Since.Equal(retry) || step.Ended != nil || step.Doing != doing {
					t.Fatalf("commands assigned to the wrong step: %+v", step)
				}
				until := f.at(2)
				act236Want(t, step.Commands[0], newCommand, "git", f.at(1), &until)
				if len(step.Marks) != 1 || step.Marks[0].Kind != "git" || step.Tools["git"] != 1 || len(step.Tools) != 1 {
					t.Fatalf("current strip includes another run's activity: %+v", step.Live)
				}
				act236SameStrip(t, got, act236Public(t, f.s, time.Now()))
				fresh := cold()
				freshView := fresh.read(t)
				if len(freshView.Steps) != 1 || !reflect.DeepEqual(freshView.Steps[0].Commands, step.Commands) {
					t.Fatalf("fresh and warmed readers disagree: warm %+v, fresh %+v", got, freshView)
				}
				act236SameStrip(t, freshView, act236Public(t, fresh.s, time.Now()))
			})
		}
	}
}

// This public-only regression fails independently of the new private route.
// A run name has no temporal meaning; changing it changes the source even
// when Issue, Doing, Since and Agent all stay identical.
func TestLiveStripUsesOnlyTheStatusRun(t *testing.T) {
	for _, provider := range []string{"claude-code", "codex"} {
		t.Run(provider, func(t *testing.T) {
			f := newAct236Fixture(t, provider)
			if err := os.RemoveAll(filepath.Dir(f.path)); err != nil {
				t.Fatal(err)
			}
			dir := filepath.Join(f.work, "owner/app/issues/issue-236")
			oldRun, currentRun := "build-z-previous", "build-a-current"
			act236Write(t, filepath.Join(dir, oldRun, "transcript.jsonl"), f.init(t)+f.start(t, "same-id", "go build ./...", 1))
			act236Write(t, filepath.Join(dir, currentRun, "transcript.jsonl"), f.init(t)+f.start(t, "same-id", "git status --short", 2))
			step := Step{Issue: 236, Doing: "building", Since: f.since, Agent: provider}
			now := time.Now()
			read := func() act236Envelope {
				now = now.Add(3 * time.Second)
				return act236Public(t, f.s, now)
			}
			wantKind := func(e act236Envelope, kind string) {
				t.Helper()
				if len(e.Steps) != 1 || e.Steps[0].Ended != nil || len(e.Steps[0].Marks) != 1 ||
					e.Steps[0].Marks[0].Kind != kind || e.Steps[0].Tools[kind] != 1 || len(e.Steps[0].Tools) != 1 {
					t.Fatalf("named run should contain only %s, got %+v", kind, e)
				}
			}
			f.status(t, act236WithRun(t, step, oldRun))
			wantKind(read(), "build")
			f.status(t, act236WithRun(t, step, currentRun))
			wantKind(read(), "git")
			for _, run := range []string{"", "build-uncreated", "build-no-transcript"} {
				if run == "build-no-transcript" {
					if err := os.Mkdir(filepath.Join(dir, run), 0o755); err != nil {
						t.Fatal(err)
					}
				}
				f.status(t, act236WithRun(t, step, run))
				warm := read()
				cold := act236Public(t, &Server{Work: f.work, Repos: f.s.Repos}, now)
				for _, e := range []act236Envelope{warm, cold} {
					for _, live := range e.Steps {
						if live.Ended == nil && (len(live.Marks) != 0 || len(live.Tools) != 0) {
							t.Fatalf("run %q fell back to another transcript: %+v", run, live)
						}
					}
				}
			}
		})
	}
}

sources.internal/factory/live_run_accept_test.go:
package factory

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/plumbing"
	"github.com/gitdek/invariant/internal/synth"
)

// A run is an opaque directory basename in the watcher's status, not a
// timestamp the dashboard interprets. Read the added field through JSON so
// these tests compile before Step gains it, and fail on the missing behavior.
type live236Event struct {
	step Step
	run  string
	dirs map[string]bool
}

type live236Call struct {
	doing, out, transcript string
}

type live236Watch struct {
	t         *testing.T
	r         *rig
	events    []live236Event
	nextEvent int
	calls     []live236Call
}

func live236Observe(t *testing.T, r *rig) *live236Watch {
	t.Helper()
	w := &live236Watch{t: t, r: r}
	// Every draft, answer, revision and retry below starts in the same
	// second, in a timezone different from the dashboard's UTC status.
	now := time.Date(2026, 10, 30, 9, 15, 12, 123000000, time.FixedZone("watcher", 9*60*60))
	r.f.Now = func() time.Time { return now }
	r.f.Activity = func(steps []Step) {
		for _, step := range steps {
			if step.Issue != 1 {
				continue
			}
			b, err := json.Marshal(step)
			if err != nil {
				t.Fatal(err)
			}
			var status struct{ Run string }
			if err := json.Unmarshal(b, &status); err != nil {
				t.Fatal(err)
			}
			root := filepath.Join(r.f.Work, "issue-1")
			entries, err := os.ReadDir(root)
			if err != nil && !errors.Is(err, os.ErrNotExist) {
				t.Fatal(err)
			}
			dirs := map[string]bool{}
			for _, entry := range entries {
				if entry.IsDir() {
					dirs[entry.Name()] = true
				}
			}
			if status.Run != "" {
				if filepath.Base(status.Run) != status.Run || status.Run == "." || status.Run == ".." {
					t.Errorf("published run %q is not a directory basename", status.Run)
				}
				if !dirs[status.Run] {
					t.Errorf("published run %q before its directory existed", status.Run)
				}
			}
			w.events = append(w.events, live236Event{step: step, run: status.Run, dirs: dirs})
		}
	}
	r.f.Formalizer = live236Formalizer{r.f.Formalizer, w}
	r.f.Builder = live236Builder{r.f.Builder, w}
	return w
}

// starting runs inside the fake agent, before it writes any transcript.
// Both the most recent Activity notification and the directory must already
// identify this exact invocation. Its first notification must precede that
// directory, even when an earlier run's transcript is still present.
func (w *live236Watch) starting(doing, out string) {
	w.t.Helper()
	name := filepath.Base(out)
	want := filepath.Join(w.r.f.Work, "issue-1", name)
	if filepath.Clean(out) != want {
		w.t.Errorf("agent output %q is outside its issue's run directory %q", out, want)
	}
	var current []live236Event
	for _, event := range w.events[w.nextEvent:] {
		if event.step.Doing == doing {
			current = append(current, event)
		}
	}
	w.nextEvent = len(w.events)
	if len(current) == 0 {
		w.t.Errorf("%s agent started without an Activity notification", doing)
	} else {
		first := current[0]
		if first.run != "" {
			w.t.Errorf("%s began with run %q; want no run until its new directory exists", doing, first.run)
		}
		if first.dirs[name] {
			w.t.Errorf("%s output %q already existed at its first status notification; a new run must get a fresh directory", doing, out)
		}
		for _, event := range current {
			if event.run != "" && event.run != name {
				w.t.Errorf("%s published run %q for output %q", doing, event.run, out)
			}
		}
		last := current[len(current)-1]
		if last.run != name {
			w.t.Errorf("%s agent started with published run %q; want output directory basename %q", doing, last.run, name)
		}
	}
	if info, err := os.Stat(out); err != nil || !info.IsDir() {
		w.t.Errorf("%s agent started before output directory %q existed: %v", doing, out, err)
	}
	for _, earlier := range w.calls {
		if earlier.out == out {
			w.t.Errorf("%s reused earlier run directory %q within the same second", doing, out)
		}
	}
	// Real agents write their transcripts here. Give each invocation a
	// distinct marker so the final check detects overwriting or deletion.
	if err := os.MkdirAll(out, 0o755); err != nil {
		w.t.Fatal(err)
	}
	transcript := fmt.Sprintf("{\"test_run\":%d}\n", len(w.calls)+1)
	if err := os.WriteFile(filepath.Join(out, "transcript.jsonl"), []byte(transcript), 0o600); err != nil {
		w.t.Fatal(err)
	}
	w.calls = append(w.calls, live236Call{doing: doing, out: out, transcript: transcript})
}

func (w *live236Watch) check(drafts, builds int) {
	w.t.Helper()
	counts := map[string]int{}
	for _, call := range w.calls {
		counts[call.doing]++
		got, err := os.ReadFile(filepath.Join(call.out, "transcript.jsonl"))
		if err != nil || string(got) != call.transcript {
			w.t.Errorf("run %q lost its own transcript: got %q, %v; want %q", call.out, got, err, call.transcript)
		}
	}
	if counts["formalizing"] != drafts || counts["building"] != builds {
		w.t.Errorf("observed %d drafts and %d builds; want %d drafts and %d builds", counts["formalizing"], counts["building"], drafts, builds)
	}
}

type live236Formalizer struct {
	Formalizer
	watch *live236Watch
}

func (a live236Formalizer) Formalize(ctx context.Context, req formalize.Request, out string) (*formalize.Result, error) {
	a.watch.starting("formalizing", out)
	return a.Formalizer.Formalize(ctx, req, out)
}

type live236Builder struct {
	Builder
	watch *live236Watch
}

func (a live236Builder) Build(ctx context.Context, dir, out string, amend bool) (*synth.Result, error) {
	a.watch.starting("building", out)
	return a.Builder.Build(ctx, dir, out, amend)
}

type live236PlanBuilder struct {
	PlanBuilder
	watch *live236Watch
	stop  bool
}

func (a *live236PlanBuilder) Build(ctx context.Context, root string, issue int, out string) (*plumbing.BuildResult, error) {
	a.watch.starting("building", out)
	if a.stop {
		return nil, errors.New("the plan's agent stopped before finishing")
	}
	return a.PlanBuilder.Build(ctx, root, issue, out)
}

// A first draft, the draft after a fork's answer, and an explicit revision
// each publish a fresh run, even though the watcher's clock has not moved.
func TestFactoryPublishesExplicitRunBeforeEveryDraft(t *testing.T) {
	r := newRig(t)
	w := live236Observe(t, r)
	r.gh.open(1, "gitdek", "Add a bounded buffer", "A buffer.\n\n/invariant solve")
	r.poll()
	r.expect(1, KindForks, LabelAsking)
	r.gh.say(1, "gitdek", "/invariant choose F1 A")
	r.poll()
	r.expect(1, KindProposal, LabelProposal)
	r.gh.say(1, "gitdek", "/invariant revise")
	r.poll()
	r.expect(1, KindProposal, LabelProposal)
	w.check(3, 0)
}

// A stopped modeled build and its retry have distinct output directories
// and status identities, while the first build's transcript remains intact.
func TestFactoryRetryUsesFreshRunForModeledBuild(t *testing.T) {
	r := newRig(t)
	w := live236Observe(t, r)
	r.build.stop = true
	stopped := ratified(t, r)
	if stopped.Marker.Kind != KindFailed || stopped.Marker.Failure != FailStopped {
		t.Fatalf("first build should stop: %+v", stopped.Marker)
	}
	r.build.stop = false
	r.gh.say(1, "gitdek", "/invariant retry")
	r.poll()
	r.expect(1, KindRatified, LabelBuilding)
	r.poll()
	r.expect(1, KindPR, LabelPR)
	w.check(1, 2)
}

// Plumbing uses a different builder entry point; it must publish the same
// run contract and reserve a fresh directory for a retry in the same second.
func TestFactoryRetryUsesFreshRunForPlumbingBuild(t *testing.T) {
	r, build := plumbingRig(t, "page/page.go")
	w := live236Observe(t, r)
	planner := &live236PlanBuilder{PlanBuilder: build, watch: w, stop: true}
	r.f.Plumbing = planner
	r.gh.open(1, "gitdek", "Add a hello page", "A page that says hello.\n\nKind: plumbing\n\n/invariant solve")
	r.poll()
	proposal := r.expect(1, KindProposal, LabelProposal)
	r.gh.say(1, "gitdek", "/invariant ratify "+strings.TrimPrefix(proposal.Marker.Proposal.Hash, "sha256:"))
	r.poll()
	stopped := r.expect(1, KindFailed, LabelHumanReview)
	if stopped.Marker.Failure != FailStopped {
		t.Fatalf("first plan build should stop: %+v", stopped.Marker)
	}
	planner.stop = false
	r.gh.say(1, "gitdek", "/invariant retry")
	r.poll()
	r.expect(1, KindRatified, LabelBuilding)
	r.poll()
	r.expect(1, KindPR, LabelPR)
	w.check(1, 2)
}
